using Strawhenge.Common.Unity.Serialization;
using System;
using UnityEngine;

namespace Strawhenge.Navigation.Unity.Destination
{
    // A cost for one or more NavMesh areas. Off-mesh links count as their area, so this prices jumps and
    // drops too: links generated by the bake are in the built-in Jump area.
    [Serializable]
    public class SerializedAreaCost
    {
        // Below 1 the pathfinding can miss the cheapest path.
        public const float MinCost = 1f;

        [SerializeField] NavMeshAreaMask _areas = new();
        [SerializeField, Min(MinCost)] float _cost = MinCost;

        public int AreaMask => _areas == null ? 0 : _areas.Value;

        // Clamped as well, as an element added in the inspector starts at 0.
        public float Cost => Mathf.Max(MinCost, _cost);
    }
}
